/**
 * Ошибки, которые могут вернуть FFI-функции ядра. Отдельный enum вместо
 * голого String — потому что uniffi умеет превращать error-enum в настоящее
 * исключение на стороне Kotlin, а строку — нет (её пришлось бы парсить руками).
 */
sealed class AlarmCoreException: kotlin.Exception() {
    
    class InstanceNotFound(
        
        val `id`: kotlin.String
        ) : AlarmCoreException() {
        override val message
            get() = "id=${ `id` }"
    }
    
    class DatabaseException(
        
        val `details`: kotlin.String
        ) : AlarmCoreException() {
        override val message
            get() = "details=${ `details` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AlarmCoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): AlarmCoreException = FfiConverterTypeAlarmCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeAlarmCoreError : FfiConverterRustBuffer<AlarmCoreException> {
    override fun read(buf: ByteBuffer): AlarmCoreException {
        

        return when(buf.getInt()) {
            1 -> AlarmCoreException.InstanceNotFound(
                FfiConverterString.read(buf),
                )
            2 -> AlarmCoreException.DatabaseException(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AlarmCoreException): ULong {
        return when(value) {
            is AlarmCoreException.InstanceNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`id`)
            )
            is AlarmCoreException.DatabaseException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
        }
    }

    override fun write(value: AlarmCoreException, buf: ByteBuffer) {
        when(value) {
            is AlarmCoreException.InstanceNotFound -> {
                buf.putInt(1)
                FfiConverterString.write(value.`id`, buf)
                Unit
            }
            is AlarmCoreException.DatabaseException -> {
                buf.putInt(2)
                FfiConverterString.write(value.`details`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Откуда взялся этот конкретный будильник — из обычного паттерна графика,
 * вручную переопределён пользователем, или это timezone-будильник (п.4.2).
 */

enum class AlarmOrigin {
    
    FROM_PATTERN,
