}


/**
 * @suppress
 */
public object FfiConverterTypeAlarmOrigin: FfiConverterRustBuffer<AlarmOrigin> {
    override fun read(buf: ByteBuffer) = try {
        AlarmOrigin.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: AlarmOrigin) = 4UL

    override fun write(value: AlarmOrigin, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





