/**
 * Паттерн графика — три принципиально разных способа задать расписание.
 * Это как раз то, что различает пресет 2/2 от кастомного графика
 * от "рандомного по приколу" (п.4.1 ТЗ).
 */
sealed class SchedulePattern {
    
    data class Cyclic(
        val `workDays`: kotlin.UByte, 
        val `restDays`: kotlin.UByte) : SchedulePattern() {
        companion object
    }
    
    data class Custom(
        val v1: List<DayType>) : SchedulePattern() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeSchedulePattern : FfiConverterRustBuffer<SchedulePattern>{
    override fun read(buf: ByteBuffer): SchedulePattern {
        return when(buf.getInt()) {
            1 -> SchedulePattern.Cyclic(
                FfiConverterUByte.read(buf),
                FfiConverterUByte.read(buf),
                )
            2 -> SchedulePattern.Custom(
                FfiConverterSequenceTypeDayType.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SchedulePattern) = when(value) {
        is SchedulePattern.Cyclic -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUByte.allocationSize(value.`workDays`)
                + FfiConverterUByte.allocationSize(value.`restDays`)
            )
        }
        is SchedulePattern.Custom -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypeDayType.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: SchedulePattern, buf: ByteBuffer) {
        when(value) {
            is SchedulePattern.Cyclic -> {
                buf.putInt(1)
                FfiConverterUByte.write(value.`workDays`, buf)
                FfiConverterUByte.write(value.`restDays`, buf)
                Unit
            }
            is SchedulePattern.Custom -> {
                buf.putInt(2)
                FfiConverterSequenceTypeDayType.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * Источник графика — чтобы отличать "взял готовый пресет 2/2"
 * от "накидал свой график руками" (п.4.1 ТЗ, визуальные бейджи).
 */
